package com.nth.desktop3d;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;

/** Reproduces the recorded dense-folder layout and checks actual icon geometry through dock changes. */
public final class DockSizing080Smoke {
    private final Instrumentation test;private MainActivity activity;private final String output;
    public DockSizing080Smoke(Instrumentation test,MainActivity activity,String output){this.test=test;this.activity=activity;this.output=output;}
    public MainActivity run()throws Exception {
        SettingsModel model=(SettingsModel)value("settingsModel");JSONObject before=DesktopBackup.capture(activity,model);
        try{
            main(()->{LauncherStore store=model.store;store.page=0;store.mode=3;store.pages.get(0).clear();for(int i=0;i<FolderRules.NAMES.length;i++){LauncherStore.Item item=new LauncherStore.Item("folder",FolderRules.NAMES[i]);item.cellX=FolderRules.X[i];item.cellY=FolderRules.Y[i];item.children.add(new LauncherStore.Item("builtin:notes","Notes"));store.pages.get(0).add(item);}store.preferences.edit().putBoolean("folder_pattern_page_0",true).putBoolean("show_dock",false).putBoolean("dock_content",false).putInt("icon_size",70).putInt("dock_space_height",96).apply();store.save();call("applySettings",new Class[]{boolean.class},true);});idle(500);
            int small=iconWidth();check(small>0,"Desktop icon was not measured");int[][] cells=positions(model.store);
            setIcon(130);int large=iconWidth();check(large>small+Ui.dp(activity,10),"Dense desktop icon size slider did not grow real icons");capture("080-large-icons-no-dock");
            main(()->model.set("show_dock",1));idle(400);check(iconWidth()==large,"Start/clock dock compressed desktop icons");main(()->model.set("dock_content",1));idle(400);check(iconWidth()==large,"Adding dock spaces compressed desktop icons");
            setIcon(70);check(iconWidth()<large-Ui.dp(activity,10),"Icon size stopped responding with both docks visible");setIcon(130);check(iconWidth()==large,"Icon size could not grow again with both docks visible");capture("080-large-icons-both-docks");
            main(()->{model.set("show_dock",0);model.set("dock_space_height",180);model.set("dock_space_count",5);});idle(450);assertDocks(false,true);check(iconWidth()==large,"Tall dock spaces compressed desktop icons");
            invoke("putDockItem",new Class[]{int.class,LauncherStore.Item.class},4,new LauncherStore.Item("builtin:settings","Settings"));assertDocks(false,true);check(model.value("show_dock")==0,"Adding dock content enabled the Start/clock dock");
            main(()->{View contents=(View)field("dockContents"),bar=(View)field("bar");int[] c=new int[2],b=new int[2];contents.getLocationOnScreen(c);bar.getLocationOnScreen(b);check(Math.abs(c[1]+contents.getHeight()-b[1]-bar.getHeight())<=1,"Hidden control dock left reserved height below spaces");});capture("080-spaces-at-bottom");
            check(Arrays.deepEquals(cells,positions(model.store)),"Dock or icon size changes altered folder cell coordinates");
            JSONObject backup=DesktopBackup.capture(activity,model);main(()->{model.set("dock_content",0);model.set("show_dock",1);});assertDocks(true,false);main(()->{try{model.importDesktopBackup(activity,new DesktopBackup.Prepared(backup,model));}catch(Exception e){throw new AssertionError(e);}});idle(350);assertDocks(false,true);check(iconWidth()==large,"Backup restore lost selected icon size");
            Instrumentation.ActivityMonitor monitor=test.addMonitor(MainActivity.class.getName(),null,false);MainActivity old=activity;main(old::recreate);activity=(MainActivity)monitor.waitForActivityWithTimeout(20000);test.removeMonitor(monitor);check(activity!=null,"Activity recreation failed");idle(700);assertDocks(false,true);check(iconWidth()==large,"Activity recreation changed desktop icon size");
            SettingsModel current=(SettingsModel)value("settingsModel");main(()->{current.set("dock_content",0);current.set("show_dock",0);});assertDocks(false,false);
            // Ordinary grids also preserve their selected size when the dock changes height.
            main(()->{current.store.preferences.edit().putBoolean("folder_pattern_page_0",false).apply();call("applySettings",new Class[]{boolean.class},true);});idle(300);int normal=iconWidth();main(()->current.set("dock_content",1));idle(350);check(iconWidth()==normal,"Ordinary desktop icons changed size after dock changes");
            invoke("showSettings",new Class[]{String.class},"dock");main(()->{check(find(activity.getWindow().getDecorView(),"Show Start and clock dock")!=null&&find(activity.getWindow().getDecorView(),"Show dock spaces")!=null,"Dock settings omitted independent visibility toggles");});capture("080-independent-dock-settings");
        }finally{SettingsModel current=(SettingsModel)value("settingsModel");main(()->{try{call("closePanel",new Class[]{});current.importDesktopBackup(activity,new DesktopBackup.Prepared(before,current));}catch(Exception e){throw new AssertionError(e);}});}
        return activity;
    }
    private int[][] positions(LauncherStore s){int[][] p=new int[s.pages.get(0).size()][2];for(int i=0;i<p.length;i++){p[i][0]=s.pages.get(0).get(i).cellX;p[i][1]=s.pages.get(0).get(i).cellY;}return p;}
    private void setIcon(int percent){invoke("showSettings",new Class[]{String.class},"home");main(()->{((SettingsStudio)field("settingsStudio")).focusSetting("icon_size");SeekBar slider=findSlider(activity.getWindow().getDecorView());check(slider!=null,"Icon size slider missing");Bundle args=new Bundle();args.putFloat("android.view.accessibility.action.ARGUMENT_PROGRESS_VALUE",(percent-70)/5f);check(slider.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),args),"Icon size slider did not accept input");});invoke("closePanel",new Class[]{});idle(250);}
    private SeekBar findSlider(View v){if(v instanceof SeekBar&&"Desktop icon size".contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return (SeekBar)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){SeekBar found=findSlider(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
    private int iconWidth(){AtomicReference<Integer> width=new AtomicReference<>(0);main(()->{DesktopView view=(DesktopView)field("desktop");try{java.lang.reflect.Field f=DesktopView.class.getDeclaredField("cellViews");f.setAccessible(true);Map<?,?> cells=(Map<?,?>)f.get(view);for(Object value:cells.values())if(value instanceof IconTile){width.set(((IconTile)value).getChildAt(0).getWidth());break;}}catch(Exception e){throw new AssertionError(e);}});return width.get();}
    private void assertDocks(boolean controls,boolean spaces){main(()->{check(((View)field("dock")).getVisibility()==(controls?View.VISIBLE:View.GONE),"Start/clock dock visibility is coupled to spaces");check(((View)field("dockContents")).getVisibility()==(spaces?View.VISIBLE:View.GONE),"Dock spaces visibility is coupled to controls");check(((View)field("bar")).getVisibility()==(controls||spaces?View.VISIBLE:View.GONE),"Empty docks reserve desktop height");check(((View)field("paging")).getVisibility()==(controls?View.VISIBLE:View.GONE),"Hidden Start/clock dock left navigation space");});}
    private View find(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&((TextView)v).getText().toString().startsWith(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),text);if(f!=null)return f;}return null;}
    private Object field(String name){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new AssertionError(e);}}
    private Object call(String name,Class<?>[] types,Object...args){try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}}
    private Object value(String name){AtomicReference<Object> result=new AtomicReference<>();main(()->result.set(call(name,new Class[]{})));return result.get();}
    private void invoke(String name,Class<?>[] types,Object...args){main(()->call(name,types,args));idle(250);}
    private void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{r.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void idle(long ms){SystemClock.sleep(ms);test.runOnMainSync(()->{});}
    private void capture(String name){idle(300);Bitmap b=test.getUiAutomation().takeScreenshot();File dir=output==null?new File(activity.getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{b.recycle();}}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
}
